    private func _generateSongBookWhammyOrBend(_ noteStart: Double, _ duration: Double, _ bendAtBeginning: Bool, _ bendValues: List<Double>, _ bendDuration: Double, _ tempoOnBeatStart: Double, _ addBend: @escaping (Double, Double) -> Void) {
