    private func _generateWhammyOrBend(_ noteStart: Double, _ duration: Double, _ playedBendPoints: List<BendPoint>, _ tempoOnBeatStart: Double, _ addBend: @escaping (Double, Double) -> Void) {
        let ticksPerPosition: Double = duration / BendPoint.MaxPosition
        do {
            var i: Double = 0.0
            while i < playedBendPoints.length - 1.0 {
                let currentPoint: BendPoint = playedBendPoints[(i).toInt()]
                let nextPoint: BendPoint = playedBendPoints[(i + 1.0).toInt()]
                let currentBendValue: Double = MidiFileGenerator.getPitchWheel(currentPoint.value)
                let nextBendValue: Double = MidiFileGenerator.getPitchWheel(nextPoint.value)
                let ticksBetweenPoints: Double = ticksPerPosition * (nextPoint.offset - currentPoint.offset)
                let tick: Double = noteStart + ticksPerPosition * currentPoint.offset
                self._generateBendValues(tick, ticksBetweenPoints, currentBendValue, nextBendValue, tempoOnBeatStart, addBend)
                i += 1
            }
        }
    }

    private func _generateBendValues(_ currentTick: Double, _ ticksBetweenPoints: Double, _ currentBendValue: Double, _ nextBendValue: Double, _ tempoOnBeatStart: Double, _ addBend: @escaping (Double, Double) -> Void) {
        var paramcurrentBendValue = currentBendValue
        var paramcurrentTick = currentTick
        let millisBetweenPoints: Double = MidiUtils.ticksToMillis(ticksBetweenPoints, tempoOnBeatStart)
        let numberOfSemitones: Double = Math.abs(nextBendValue - paramcurrentBendValue) / MidiFileGenerator._pitchValuePerSemitone
        let numberOfSteps: Double = Math.max(MidiFileGenerator._minBreakpointsPerSemitone * numberOfSemitones, millisBetweenPoints / MidiFileGenerator._millisecondsPerBreakpoint)
        let ticksPerBreakpoint: Double = ticksBetweenPoints / numberOfSteps
        let pitchPerBreakpoint: Double = (nextBendValue - paramcurrentBendValue) / numberOfSteps
        let endTick: Double = paramcurrentTick + ticksBetweenPoints
        do {
            var i: Double = 0.0
            while i < numberOfSteps {
                addBend(jsOr(paramcurrentTick, 0), Math.round(paramcurrentBendValue))
                paramcurrentBendValue += pitchPerBreakpoint
                paramcurrentTick += ticksPerBreakpoint
                i += 1
            }
        }
        addBend(jsOr(endTick, 0), nextBendValue)
    }

    private func _generateRasgueado(_ track: Track, _ note: Note, _ noteStart: Double, _ noteKey: Double, _ velocity: Double, _ channel: Double, _ rasgueadoInfo: RasgueadoInfo) {
        var tick: Double = noteStart
        do {
            var i: Double = 0.0
            while i < rasgueadoInfo.durations.length {
                let brushInfo: Int32Array = rasgueadoInfo.brushInfos[(i).toInt()]
                let brushOffset: Double = note.isStringed && note.string <= brushInfo.length ? brushInfo[(note.string - 1.0).toInt()] : 0.0
                let duration: Double = rasgueadoInfo.durations[(i).toInt()]
                self._handler.addNote(track.index, tick + brushOffset, duration - brushOffset, noteKey, velocity, channel)
                tick += duration
                i += 1
            }
        }
    }

    private func _generateTrill(_ note: Note, _ noteStart: Double, _ noteDuration: MidiNoteDuration, _ noteKey: Double, _ dynamicValue: Double, _ channel: Double) {
        let track: Track = note.beat.voice.bar.staff.track
        let trillKey: Double = note.stringTuning + note.trillFret
        var trillLength: Double = MidiUtils.toTicks(note.trillSpeed)
        var realKey: Bool = true
        var tick: Double = noteStart
        let end: Double = noteStart + noteDuration.untilTieOrSlideEnd
        while tick + 10.0 < end {
            if tick + trillLength >= end {
                trillLength = end - tick
            }
            self._handler.addNote(track.index, tick, trillLength, realKey ? noteKey : trillKey, dynamicValue, channel)
            realKey = !realKey
            tick += trillLength
        }
    }

    private func _generateTremoloPicking(_ note: Note, _ noteStart: Double, _ noteDuration: MidiNoteDuration, _ noteKey: Double, _ dynamicValue: Double, _ channel: Double) throws {
        let track: Track = note.beat.voice.bar.staff.track
        let marks: Double = try jsNonNull(note.beat.tremoloPicking).marks
        if marks == 0.0 {
            return
        }
        var tpLength: Double = try jsNonNull(note.beat.tremoloPicking).getDurationAsTicks(note.beat.duration) * noteDuration.beatDurationFactor
        var tick: Double = noteStart
        let end: Double = noteStart + noteDuration.untilTieOrSlideEnd
        while tick + 10.0 < end {
            if tick + tpLength >= end {
                tpLength = end - tick
            }
            self._handler.addNote(track.index, tick, tpLength, noteKey, dynamicValue, channel)
            tick += tpLength
        }
    }

