    private func _getRasgueadoInfo(_ beat: Beat, _ beatDuration: Double) throws -> RasgueadoInfo? {
        if !beat.hasRasgueado {
            return nil
        }
        let info: RasgueadoInfo = RasgueadoInfo()
        let rasgueadoPattern: List<Double> = try jsNonNull(MidiFileGenerator._rasgueadoDurations.get(beat.rasgueado))
        let patternDuration: Double = rasgueadoPattern.reduce({ (p: Double, v: Double) -> Double in
            return p + v
        }, 0.0)
        try info.durations = jsNonNull(MidiFileGenerator._rasgueadoDurations.get(beat.rasgueado)).map({ (v: Double) -> Double in
            return (beatDuration * v) / patternDuration
        })
        info.brushInfos = List<Int32Array>((info.durations.length).toInt())
        let sixteenthBrush: Double = MidiUtils.toTicks(Duration.Sixteenth)
        var stringUsed: Double = 0.0
        var stringCount: Double = 0.0
        for n in beat.notes {
            if n.isTieDestination {
                continue
            }
            stringUsed = jsOr(stringUsed, jsShl(1, n.string - 1.0))
            stringCount += 1
        }
        let rasgueadoDirections: List<BrushType> = try jsNonNull(MidiFileGenerator._rasgueadoDirections.get(beat.rasgueado))
        do {
            var i: Double = 0.0
            while i < info.durations.length {
                let brushDuration: Double = (info.durations[(i).toInt()] * sixteenthBrush) / MidiUtils.QuarterTime
                let brushInfo: Int32Array = Int32Array(beat.voice.bar.staff.tuning.length)
                info.brushInfos[(i).toInt()] = (brushInfo as! Int32Array)
                let brushType: BrushType = rasgueadoDirections[(i).toInt()]
                if brushType != BrushType.None {
                    self._fillBrushInfo(beat, (brushInfo as! Int32Array), brushType == BrushType.ArpeggioDown || brushType == BrushType.BrushDown, stringUsed, stringCount, brushDuration)
                }
                i += 1
            }
        }
        return info
    }

    private func _getBrushInfo(_ beat: Beat) -> Int32Array {
        let brushInfo: Int32Array = Int32Array(beat.voice.bar.staff.tuning.length)
        if TypeHelper.isTruthy(beat.brushType) {
            var stringUsed: Double = 0.0
            var stringCount: Double = 0.0
            for n in beat.notes {
                if n.isTieDestination {
                    continue
                }
                stringUsed = jsOr(stringUsed, jsShl(1, n.string - 1.0))
                stringCount += 1
            }
            self._fillBrushInfo(beat, (brushInfo as! Int32Array), beat.brushType == BrushType.ArpeggioDown || beat.brushType == BrushType.BrushDown, stringUsed, stringCount, beat.brushDuration)
        }
        return (brushInfo as! Int32Array)
    }

    private func _fillBrushInfo(_ beat: Beat, _ brushInfo: Int32Array, _ down: Bool, _ stringUsed: Double, _ stringCount: Double, _ brushDuration: Double) -> Int32Array {
        if beat.notes.length > 0 {
            var brushMove: Double = 0.0
            let brushIncrement: Double = jsOr(brushDuration / (stringCount - 1.0), 0)
            do {
                var i: Double = 0.0
                while i < beat.voice.bar.staff.tuning.length {
                    let index: Double = down ? i : brushInfo.length - 1.0 - i
                    if (jsAnd(stringUsed, jsShl(1, index))) != 0 {
                        brushInfo[(index).toInt()] = brushMove
                        brushMove += brushIncrement
                    }
                    i += 1
                }
            }
        }
        return brushInfo
    }

    private func _generateNonTempoAutomation(_ beat: Beat, _ automation: Automation, _ startMove: Double) {
        switch automation.type {
        case AutomationType.Instrument:
            self._addProgramChange(beat.voice.bar.staff.track, beat.playbackStart + startMove, beat.voice.bar.staff.track.playbackInfo.primaryChannel, jsAnd(jsOr(automation.value, 0), 255))
            self._addProgramChange(beat.voice.bar.staff.track, beat.playbackStart + startMove, beat.voice.bar.staff.track.playbackInfo.secondaryChannel, jsAnd(jsOr(automation.value, 0), 255))
        case AutomationType.Bank:
            self._addBankChange(beat.voice.bar.staff.track, beat.playbackStart + startMove, beat.voice.bar.staff.track.playbackInfo.primaryChannel, automation.value)
            self._addBankChange(beat.voice.bar.staff.track, beat.playbackStart + startMove, beat.voice.bar.staff.track.playbackInfo.secondaryChannel, automation.value)
        case AutomationType.Balance:
            let balance: Double = MidiFileGenerator._toChannelShort(automation.value)
            self._handler.addControlChange(beat.voice.bar.staff.track.index, beat.playbackStart + startMove, beat.voice.bar.staff.track.playbackInfo.primaryChannel, ControllerType.PanCoarse, balance)
            self._handler.addControlChange(beat.voice.bar.staff.track.index, beat.playbackStart + startMove, beat.voice.bar.staff.track.playbackInfo.secondaryChannel, ControllerType.PanCoarse, balance)
        case AutomationType.Volume:
            let volume: Double = MidiFileGenerator._toChannelShort(automation.value)
            self._handler.addControlChange(beat.voice.bar.staff.track.index, beat.playbackStart + startMove, beat.voice.bar.staff.track.playbackInfo.primaryChannel, ControllerType.VolumeCoarse, volume)
            self._handler.addControlChange(beat.voice.bar.staff.track.index, beat.playbackStart + startMove, beat.voice.bar.staff.track.playbackInfo.secondaryChannel, ControllerType.VolumeCoarse, volume)
        default:
            break
        }
    }

    public func prepareSingleBeat(_ beat: Beat) -> Double {
        var tempo: Double = -1.0
        var program: Double = -1.0
        var currentBeat: Beat? = beat
        while TypeHelper.isTruthy(TypeHelper.isTruthy(currentBeat) && (tempo == -1.0 || program == -1.0)) {
            for automation in beat.automations {
                switch automation.type {
                case AutomationType.Instrument:
                    program = automation.value
                case AutomationType.Tempo:
                    tempo = automation.value
                default:
                    break
                }
            }
            currentBeat = currentBeat!.previousBeat
        }
        let track: Track = beat.voice.bar.staff.track
        let masterBar: MasterBar = beat.voice.bar.masterBar
        if tempo == -1.0 {
            tempo = masterBar.score.tempo
        }
        let positionRatio: Double = ModelUtils.tickToRatioPosition(masterBar, beat.playbackStart)
        for automation in masterBar.tempoAutomations {
            if automation.ratioPosition <= positionRatio {
                tempo = automation.value
            } else {
                break
            }
        }
        if program == -1.0 {
            program = track.playbackInfo.program
        }
        let volume: Double = track.playbackInfo.volume
        self._generateTrack(track)
        self._handler.addTimeSignature(0.0, masterBar.timeSignatureNumerator, masterBar.timeSignatureDenominator)
        self._handler.addTempo(0.0, tempo)
        let volumeCoarse: Double = MidiFileGenerator._toChannelShort(volume)
        self._handler.addControlChange(0.0, 0.0, track.playbackInfo.primaryChannel, ControllerType.VolumeCoarse, volumeCoarse)
        self._handler.addControlChange(0.0, 0.0, track.playbackInfo.secondaryChannel, ControllerType.VolumeCoarse, volumeCoarse)
        return tempo
    }

    public func generateSingleBeat(_ beat: Beat) throws {
        let tempo: Double = self.prepareSingleBeat(beat)
        try self._generateBeat(beat, -beat.playbackStart, beat.voice.bar, tempo)
    }

    public func generateSingleNote(_ note: Note) throws {
        let tempo: Double = self.prepareSingleBeat(note.beat)
        try self._generateNote(note, 0.0, note.beat.playbackDuration, tempo, Int32Array(note.beat.voice.bar.staff.tuning.length), nil)
    }
}

internal final class MidiNoteDuration {
    public var noteOnly: Double = 0.0

    public var untilTieOrSlideEnd: Double = 0.0

    public var letRingEnd: Double = 0.0

    /**
     * A factor indicating how much longer/shorter the beat is in its playback respecting
     * effects like tuplets, triplet feels, dots, grace beats stealing parts etc.
     *
     * This factor can be used to relatively adjust durations in effects like trills or tremolos.
     */
    public var beatDurationFactor: Double = 1.0

    public init() {}
}

internal final class TripletFeelDurations {
    public var firstBeatDuration: Double = 0.0

    public var secondBeatStartOffset: Double = 0.0

    public var secondBeatDuration: Double = 0.0

    public init() {}
}

internal final class RasgueadoInfo {
    public var durations: List<Double> = List<Double>()

    public var brushInfos: List<Int32Array> = List<Int32Array>()

    public init() {}
}

internal final class PlayThroughContext {
    public var synthTick: Double = 0.0

    public var synthTime: Double = 0.0

    public var currentTempo: Double = 0.0

    public var automationToSyncPoint: Map<Automation, BackingTrackSyncPoint> = Map<Automation, BackingTrackSyncPoint>()

    public var syncPoints: List<BackingTrackSyncPoint>!

    public var createNewSyncPoints: Bool = false

    public init() {}
}
